const c = P.c;   // coefficient: solve sin(2x) = c*cos(x)
// Identity: sin(2x) = 2 sinx cosx, so sin(2x) - c cosx = cosx(2 sinx - c).
// Roots: cosx = 0  OR  sinx = c/2.
const lhs = x => Math.sin(2 * x);
const rhs = x => c * Math.cos(x);
v.fn(lhs, { color: H.colors.accent, width: 2.6 });
v.fn(rhs, { color: H.colors.accent2, width: 2.6 });
// difference curve whose zeros ARE the solutions
v.fn(x => Math.sin(2 * x) - c * Math.cos(x), { color: H.colors.violet, width: 1.6 });
// mark the factored roots on [0, 2π)
const roots = [Math.PI / 2, 3 * Math.PI / 2];  // cosx = 0 always
const r = c / 2;
if (Math.abs(r) <= 1) {
  const b = Math.asin(r);
  roots.push((b + 2 * Math.PI) % (2 * Math.PI));
  roots.push((Math.PI - b + 2 * Math.PI) % (2 * Math.PI));
}
for (let i = 0; i < roots.length; i++) v.dot(roots[i], 0, { r: 6, fill: H.colors.good });
